-- confesion-reales.sql — alinea SOLO tc2_confesion (32 bloques). Busca sacramento_id por slug (sin UUID hardcodeado).
-- Correr en el SQL Editor de Supabase. Idempotente: borra y re-siembra tc2_confesion.

DELETE FROM public.preguntas WHERE video_id IN (SELECT id FROM public.videos WHERE sacramento_id=(SELECT id FROM public.sacramentos WHERE slug='tc2_confesion'));
DELETE FROM public.intentos_evaluacion WHERE video_id IN (SELECT id FROM public.videos WHERE sacramento_id=(SELECT id FROM public.sacramentos WHERE slug='tc2_confesion'));
DELETE FROM public.encuestas_video WHERE video_id IN (SELECT id FROM public.videos WHERE sacramento_id=(SELECT id FROM public.sacramentos WHERE slug='tc2_confesion'));
DELETE FROM public.progreso_videos WHERE video_id IN (SELECT id FROM public.videos WHERE sacramento_id=(SELECT id FROM public.sacramentos WHERE slug='tc2_confesion'));
DELETE FROM public.accesos_video WHERE video_id IN (SELECT id FROM public.videos WHERE sacramento_id=(SELECT id FROM public.sacramentos WHERE slug='tc2_confesion'));
DELETE FROM public.videos WHERE sacramento_id=(SELECT id FROM public.sacramentos WHERE slug='tc2_confesion');
